import axios from "axios";

const dataOption = (muscleChoice) => {
  const options = {
    method: 'GET',
    headers: {
      'X-RapidAPI-Key': 'f58c1e6a5fmsh60b58fa6f57d204p1d84ccjsne12cdca5d8ba',
      'X-RapidAPI-Host': 'exercisedb.p.rapidapi.com'
    }
  };

  const url = `https://exercisedb.p.rapidapi.com/exercises/bodyPart/${muscleChoice}?limit=10&offset=0`;

  return fetch(url, options)
    .then(response => {
      if (!response.ok) throw new Error("Erro ao buscar dados da API");
      return response.json();
    })
    .then(data => {
      console.log("Dados recebidos:", data);
      return data;
    })
    .catch(err => {
      console.error("Erro na chamada à API:", err);
    });
};

const getData = async (muscle) => {
  try {
    const response = await axios.request(dataOption(muscle));
    return response.data;
  } catch (error) {
    console.error(error?.response?.data || error.message);
  }
};

export default getData;
